CREATE TABLE "c_Customer" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Customer_customer_name" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Customer','PreferredCustomer')));
CREATE TABLE "c_Order" ("id" BIGINT NOT NULL, "a_Order_order_value" DOUBLE PRECISION NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_PreferredCustomer" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_PreferredCustomer_discount" DOUBLE PRECISION NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('PreferredCustomer')));
CREATE TABLE "l_CustomerOrders" ("r_CustomerOrders_source_id" BIGINT NOT NULL, "r_CustomerOrders_source_dtype" TEXT NOT NULL, "r_CustomerOrders_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_target_id"), UNIQUE ("r_CustomerOrders_target_id"), CHECK ("r_CustomerOrders_source_dtype" IS NULL OR "r_CustomerOrders_source_dtype" IN ('Customer','PreferredCustomer')));
ALTER TABLE "c_PreferredCustomer" ADD CONSTRAINT "fk_c_PreferredCustomer_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Customer" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerOrders" ADD CONSTRAINT "fk_l_CustomerOrders_0" FOREIGN KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_source_dtype") REFERENCES "c_Customer" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerOrders" ADD CONSTRAINT "fk_l_CustomerOrders_1" FOREIGN KEY ("r_CustomerOrders_target_id") REFERENCES "c_Order" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_CustomerOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Order" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CustomerOrders" l WHERE l."r_CustomerOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CustomerOrders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CustomerOrders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Order" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerOrders"();
CREATE CONSTRAINT TRIGGER "ct_CustomerOrders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CustomerOrders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerOrders"();